def _copy_defaults() -> list[dict]:
    return [dict(item) for item in DEFAULT_RECIPIENTS]


def save_recipients(items: list[dict]) -> None:
    try:
        with open(RECIPIENTS_FILE, "w", encoding="utf-8") as f:
            json.dump(items, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def load_recipients() -> list[dict]:
    if not os.path.exists(RECIPIENTS_FILE):
        defaults = _copy_defaults()
        save_recipients(defaults)
        return defaults

    try:
        with open(RECIPIENTS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, list) or len(data) == 0:
            defaults = _copy_defaults()
            save_recipients(defaults)
            return defaults

        defaults_by_name = {
            (d.get("name") or "").strip().lower(): d for d in DEFAULT_RECIPIENTS
        }
        changed = False
        upgraded = []
        seen_keys = set()

        for item in data:
            if not isinstance(item, dict):
                continue
            r = dict(item)
            name = (r.get("name") or "").strip()
            key = name.lower()
            seen_keys.add(key)

            rec_type = r.get("recipient_type", "ФИЗ. ЛИЦО")
            if "company" not in r or "fio" not in r:
                r["company"] = name if rec_type == "ЮР. ЛИЦО" else ""
                r["fio"] = name
                changed = True

            # Если в локальном файле у юрлица в ФИО стоит название фирмы,
            # а во вшитой базе уже есть реальная фамилия — обновляем автоматически
            d = defaults_by_name.get(key)
            if d and rec_type == "ЮР. ЛИЦО":
                cur_comp = (r.get("company") or "").strip()
                cur_fio = (r.get("fio") or "").strip()
                def_fio = (d.get("fio") or "").strip()
                def_comp = (d.get("company") or "").strip()
                if def_fio and def_fio != def_comp and (not cur_fio or cur_fio == cur_comp):
                    r["company"] = def_comp
                    r["fio"] = def_fio
                    changed = True

            upgraded.append(r)

        # Добавляем новых клиентов из вшитой базы, которых не было в старом файле
        for d in DEFAULT_RECIPIENTS:
            dk = (d.get("name") or "").strip().lower()
            if dk not in seen_keys:
                upgraded.append(dict(d))
                seen_keys.add(dk)
                changed = True

        if changed:
            save_recipients(upgraded)
        return upgraded
    except Exception:
        defaults = _copy_defaults()
        save_recipients(defaults)
        return defaults


def load_history() -> list[dict]:
    if not os.path.exists(HISTORY_FILE):
        return []
    try:
        with open(HISTORY_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def add_history_entry(entry: dict) -> None:
    history = load_history()
    item = dict(entry)
    item.setdefault("created_at", datetime.datetime.now().strftime("%d.%m.%Y %H:%M"))
    history.insert(0, item)
    history = history[:300]
    try:
        with open(HISTORY_FILE, "w", encoding="utf-8") as f:
            json.dump(history, f, ensure_ascii=False, indent=2)
    except Exception:
        pass
